"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Field, FieldDescription, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  ClaimChip,
  ClaimsList,
  claimRowsFromPolicy,
  claimsListValid,
  mergeClaimRows,
  type ClaimRow,
} from "@/components/oidc/claims"
import type { OidcPolicy } from "@/lib/oidc/policy"

function VeilIcon({ ...props }: React.ComponentProps<"svg">) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" {...props}>
      <rect x="4" y="10" width="16" height="10" rx="2" />
      <path d="M8 10V7a4 4 0 0 1 8 0v3" />
    </svg>
  )
}

type Fields = {
  agentId: string
  audience: string
  extraClaims: ClaimRow[]
}

const DEFAULTS: Fields = {
  agentId: "",
  audience: "veil",
  extraClaims: [],
}

const FIRST_CLASS_CLAIMS = ["aud", "sub"]

const ISSUER = "https://id.veil.nyc"

function compile(fields: Fields): OidcPolicy {
  const claims: Record<string, string[]> = {}
  if (fields.audience) {
    claims.aud = [fields.audience]
  }
  if (fields.agentId) {
    const raw = fields.agentId.trim()
    claims.sub = [raw.startsWith("agent-") ? raw : `agent-${raw}`]
  }
  mergeClaimRows(claims, fields.extraClaims, FIRST_CLASS_CLAIMS)
  return { issuer: ISSUER, claims }
}

function parse(policy: OidcPolicy): Fields | null {
  if (policy.issuer !== ISSUER) {
    return null
  }
  if (
    FIRST_CLASS_CLAIMS.some((name) => (policy.claims[name]?.length ?? 0) > 1)
  ) {
    return null
  }
  const extraClaims = claimRowsFromPolicy(policy.claims, FIRST_CLASS_CLAIMS)
  if (extraClaims === null) {
    return null
  }
  const rawSub = policy.claims.sub?.[0] ?? ""
  return {
    agentId: rawSub.startsWith("agent-") ? rawSub.slice("agent-".length) : rawSub,
    audience: policy.claims.aud?.[0] ?? "",
    extraClaims,
  }
}

function matchesVeilPolicy(policy: OidcPolicy) {
  return parse(policy) !== null
}

function VeilPolicyForm({
  defaultValue,
  onChange,
  onSubmit,
  className,
}: {
  defaultValue?: OidcPolicy
  onChange?: (policy: OidcPolicy) => void
  onSubmit: (policy: OidcPolicy) => void
  className?: string
}) {
  const [fields, setFields] = React.useState(() =>
    defaultValue ? (parse(defaultValue) ?? DEFAULTS) : DEFAULTS
  )

  const apply = (next: Fields) => {
    setFields(next)
    const policy = compile(next)
    onChange?.(
      defaultValue?.label ? { ...policy, label: defaultValue.label } : policy
    )
  }

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault()
    if (
      !(
        Boolean(fields.agentId && fields.audience) &&
        claimsListValid(fields.extraClaims, FIRST_CLASS_CLAIMS)
      )
    ) {
      return
    }
    const policy = compile(fields)
    onSubmit(
      defaultValue?.label ? { ...policy, label: defaultValue.label } : policy
    )
  }

  return (
    <form onSubmit={handleSubmit} className={cn("space-y-4", className)}>
      <Field>
        <FieldLabel>
          Issuer <ClaimChip>iss</ClaimChip>
        </FieldLabel>
        <Input value={ISSUER} readOnly />
        <FieldDescription>Fixed for Veil agent identity tokens.</FieldDescription>
      </Field>
      <Field>
        <FieldLabel>
          Agent ID <ClaimChip>sub</ClaimChip>
        </FieldLabel>
        <Input
          value={fields.agentId}
          placeholder="cursor"
          onChange={(event) =>
            apply({ ...fields, agentId: event.target.value.trim() })
          }
        />
        <FieldDescription>Compiled to subject agent-&lt;name&gt;.</FieldDescription>
      </Field>
      <Field>
        <FieldLabel>
          Audience <ClaimChip>aud</ClaimChip>
        </FieldLabel>
        <Input
          value={fields.audience}
          placeholder="veil"
          onChange={(event) =>
            apply({ ...fields, audience: event.target.value.trim() })
          }
        />
      </Field>
      <ClaimsList
        value={fields.extraClaims}
        onChange={(rows) => apply({ ...fields, extraClaims: rows })}
        reserved={FIRST_CLASS_CLAIMS}
      />
      <Button type="submit">Save</Button>
    </form>
  )
}

export { VeilIcon, VeilPolicyForm, matchesVeilPolicy }
